#include "rocks/mesh.hpp"
#include <iostream>
#include <stdexcept>
using namespace rocks;
#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(0)
std::vector<Plane> box(Vec3 lo,Vec3 hi){return {{{1,0,0},hi.x},{{-1,0,0},-lo.x},{{0,1,0},hi.y},{{0,-1,0},-lo.y},{{0,0,1},hi.z},{{0,0,-1},-lo.z}};}
int main(){try{Recipe r;r.schemaVersion=2;r.generatorVersion="rocks-v3";r.extractorVersion="poly-csg-v1";r.family="fractured_wall";r.wear=0;RockField f{r,box({-1,-1,-1},{1,1,1}),{},.08,{}};auto base=extractPolyhedral(f,Stage::Base);CHECK(validate(base.mesh,2).accepted);CHECK(base.mesh.cornerNormals.size()==base.mesh.indices.size());for(std::size_t i=0;i<base.mesh.indices.size();i+=3){auto a=base.mesh.positions[base.mesh.indices[i]],b=base.mesh.positions[base.mesh.indices[i+1]],c=base.mesh.positions[base.mesh.indices[i+2]];CHECK(dot(base.mesh.cornerNormals[i],normalized(cross(b-a,c-a)))>.999999);}CHECK(std::abs(validate(base.mesh,2).signedVolume-8)<1e-8);f.fractures={box({-.25,-.25,0},{.25,.25,2})};auto cut=extractPolyhedral(f,Stage::Stratified);auto report=validate(cut.mesh,2);for(auto e:report.errors)std::cerr<<e<<'\n';CHECK(report.accepted);CHECK(std::abs(report.signedVolume-7.75)<1e-8);f.fractures.push_back(f.fractures[0]);auto duplicate=extractPolyhedral(f,Stage::Stratified);CHECK(validate(duplicate.mesh,2).accepted);CHECK(std::abs(validate(duplicate.mesh,2).signedVolume-7.75)<1e-8);f.fractures={box({-1,-1,1},{1,1,2})};auto coplanar=extractPolyhedral(f,Stage::Stratified);CHECK(validate(coplanar.mesh,2).accepted);CHECK(std::abs(validate(coplanar.mesh,2).signedVolume-8)<1e-8);f.fractures={box({-.5,-.5,0},{0,0,2}),box({0,0,0},{.5,.5,2})};bool rejected=false;try{rejected=!validate(extractPolyhedral(f,Stage::Stratified).mesh,2).accepted;}catch(const std::runtime_error&){rejected=true;}CHECK(rejected);f.fractures={box({-.25,-.25,0},{.25,.25,2})};f.fractures[0].push_back({{1,0,0},.25+1e-9});rejected=false;try{extractPolyhedral(f,Stage::Stratified);}catch(const std::invalid_argument&){rejected=true;}CHECK(rejected);
 std::cout<<"polyhedral analytic-volume agreement/coplanarity/repeated-cut tests PASS\n";}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
